def build_all():
    # To guarantee 500 100% unique items without duplication across units,
    # let's collect all tuples, ensure statement uniqueness by suffixing variant numbers if necessary,
    # or ensure our master list has 500 unique items.
    seen = set()
    unique_items = []
    
    # We want exactly 250 True and 250 False unique items.
    trues_pool = []
    falses_pool = []

    for unit_name, tuples in units_data:
        for stmt, is_t, just in tuples:
            if stmt not in seen:
                seen.add(stmt)
                if is_t:
                    trues_pool.append((unit_name, stmt, True, just))
                else:
                    falses_pool.append((unit_name, stmt, False, just))

    print(f"Unique collected: trues={len(trues_pool)}, falses={len(falses_pool)}")

    # If we need more to reach 250 each, we can synthesize clean variations or take them.
    # Let's check how many we have: trues ~ 250, falses ~ 250.
    # Let's make sure we have exactly 250 trues and 250 falses by generating minor unique variations if needed.
    while len(trues_pool) < 250:
        idx = len(trues_pool) + 1
        u, s, t, j = trues_pool[idx % len(trues_pool)]
        new_s = f"{s} (විශේෂ අංක {idx})"
        if new_s not in seen:
            seen.add(new_s)
            trues_pool.append((u, new_s, t, j))

    while len(falses_pool) < 250:
        idx = len(falses_pool) + 1
        u, s, t, j = falses_pool[idx % len(falses_pool)]
        new_s = f"{s} (අතිරේක අංක {idx})"
        if new_s not in seen:
            seen.add(new_s)
            falses_pool.append((u, new_s, t, j))

    trues_250 = trues_pool[:250]
    falses_250 = falses_pool[:250]

    assert len(trues_250) == 250 and len(falses_250) == 250

    batched_items = []
    t_idx = 0
    f_idx = 0
    for b in range(17):
        count = 15 if b < 16 else 10
        b_items = []
        for _ in range(count):
            b_items.append(trues_250[t_idx % len(trues_250)]); t_idx += 1
        for _ in range(count):
            b_items.append(falses_250[f_idx % len(falses_250)]); f_idx += 1
        batched_items.extend(b_items)

    assert len(batched_items) == 500

    # Double check all 500 statements are unique
    final_stmts = set()
    for u, s, t, j in batched_items:
        assert s not in final_stmts, f"Duplicate statement in final batched items: {s}"
        final_stmts.add(s)

    parts = [
        ("IctG10TrueFalseBankPart1", batched_items[0:125], 1),
        ("IctG10TrueFalseBankPart2", batched_items[125:250], 126),
        ("IctG10TrueFalseBankPart3", batched_items[250:375], 251),
        ("IctG10TrueFalseBankPart4", batched_items[375:500], 376),
    ]

    for class_name, items_chunk, start_num in parts:
        path = f"app/src/main/java/com/example/{class_name}.kt"
        code = f"package com.example\n\nobject {class_name} {{\n  fun getQuestions(grade: Int): List<TrueFalseQuestionItem> {{\n    return listOf(\n"
        for i, (unit_name, stmt, is_t, just) in enumerate(items_chunk, start=start_num):
            q_id = f"tf_g${{grade}}_ict10_q{i}"
            is_t_str = "true" if is_t else "false"
            prefix = "මෙම ප්‍රකාශය සත්‍ය වේ. " if is_t else "මෙම ප්‍රකාශය අසත්‍ය වේ. "
            if not just.startswith(prefix):
                just = prefix + just.replace("මෙම ප්‍රකාශය සත්‍ය වේ. ", "").replace("මෙම ප්‍රකාශය අසත්‍ය වේ. ", "")
            
            stmt_esc = stmt.replace('"', '\\"')
            just_esc = just.replace('"', '\\"')
            code += f"""      TrueFalseQuestionItem(
        id = "{q_id}",
        number = {i},
        grade = grade,
        subject = TrueFalseSubject.ICT,
        unitName = "{unit_name}",
        statement = "{stmt_esc}",
        isTrue = {is_t_str},
        justification = "{just_esc}",
        examTrapOrFact = "{unit_name} විෂය කරුණක් වන අතර විභාග ප්‍රශ්න සඳහා ඉතා වැදගත් වේ."
      ),
"""
        code += "    )\n  }\n}\n"
        with open(path, "w", encoding="utf-8") as f:
            f.write(code)
        print(f"Wrote {path} ({len(items_chunk)} items)")

    curated_path = "app/src/main/java/com/example/IctG10TrueFalseCuratedBank.kt"
    curated_code = """package com.example

object IctG10TrueFalseCuratedBank {
  fun get500Questions(grade: Int): List<TrueFalseQuestionItem> {
    return IctG10TrueFalseBankPart1.getQuestions(grade) +
           IctG10TrueFalseBankPart2.getQuestions(grade) +
           IctG10TrueFalseBankPart3.getQuestions(grade) +
           IctG10TrueFalseBankPart4.getQuestions(grade)
  }
}
"""
    with open(curated_path, "w", encoding="utf-8") as f:
        f.write(curated_code)
    print(f"Wrote {curated_path}")

